import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

fused_ops_source = r"""
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <float.h>
#include <math.h>

// Approximate GELU
__device__ __forceinline__ float gelu(float x) {
    float c = 0.044715f;
    float x_cubed = x * x * x;
    float inner = 0.7978845608f * (x + c * x_cubed);
    return 0.5f * x * (1.0f + tanhf(inner));
}

// Kernel 1: AvgPool1d (by chunk) -> GELU -> scale
__global__ void fused_pool_gelu_scale_kernel(
    const float* __restrict__ in,
    float* __restrict__ out,
    int B, int C, int pool_kernel_size,
    float scale_factor
){
    int total = B * (C / pool_kernel_size);
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx >= total) return;
    int C_new = C / pool_kernel_size;
    int b = idx / C_new;
    int c_out = idx % C_new;
    int c_start = c_out * pool_kernel_size;
    float sum_val = 0.0f;
    for(int i = 0; i < pool_kernel_size; i++){
        sum_val += in[b*C + (c_start + i)];
    }
    float avg_val = sum_val / (float)pool_kernel_size;
    float g = gelu(avg_val);
    out[idx] = g * scale_factor;
}

// Kernel 2: Max along dim=1
__global__ void fused_max_kernel(
    const float* __restrict__ in,
    float* __restrict__ out,
    int B, int C_new
){
    int b = blockIdx.x;
    float max_val = -FLT_MAX;
    for(int i = 0; i < C_new; i++){
        float val = in[b*C_new + i];
        if(val > max_val){
            max_val = val;
        }
    }
    out[b] = max_val;
}

torch::Tensor fused_pool_gelu_scale(
    torch::Tensor x,
    int pool_kernel_size,
    double scale_factor
){
    // x shape: (B, C)
    int B = x.size(0);
    int C = x.size(1);
    auto out = torch::empty({B, C / pool_kernel_size}, x.options());
    int total = B * (C / pool_kernel_size);

    int blockSize = 256;
    int gridSize = (total + blockSize - 1) / blockSize;

    fused_pool_gelu_scale_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C, pool_kernel_size,
        static_cast<float>(scale_factor)
    );

    return out;
}

torch::Tensor fused_max(torch::Tensor x){
    // x shape: (B, C_new)
    int B = x.size(0);
    int C_new = x.size(1);
    auto out = torch::empty({B}, x.options());

    fused_max_kernel<<<B, 1>>>(
        x.data_ptr<float>(),
        out.data_ptr<float>(),
        B, C_new
    );

    return out;
}
"""

fused_ops_cpp_source = r"""
torch::Tensor fused_pool_gelu_scale(torch::Tensor x, int pool_kernel_size, double scale_factor);
torch::Tensor fused_max(torch::Tensor x);
"""

fused_ops = load_inline(
    name="fused_ops",
    cpp_sources=fused_ops_cpp_source,
    cuda_sources=fused_ops_source,
    functions=["fused_pool_gelu_scale", "fused_max"],
    verbose=False
)

class ModelNew(nn.Module):
    def __init__(self, in_features, out_features, pool_kernel_size, scale_factor):
        super(ModelNew, self).__init__()
        self.weight = nn.Parameter(torch.randn(out_features, in_features))
        self.bias = nn.Parameter(torch.randn(out_features))
        self.pool_kernel_size = pool_kernel_size
        self.scale_factor = scale_factor

    def forward(self, x):
        # Linear
        x = torch.nn.functional.linear(x, self.weight, self.bias)
        # Fused AvgPool -> GELU -> scale
        x = fused_ops.fused_pool_gelu_scale(x, self.pool_kernel_size, self.scale_factor)
        # Fused max over dim=1
        x = fused_ops.fused_max(x)
        return x

